// ============================================================
// Prepare Keyframes for Face Recognition
// ============================================================
// After ffmpeg extracts keyframes, this node creates an array
// of items — one per keyframe — so each can be sent to CompreFace.
// ============================================================

const item = $input.first();
const mediaId = item.json.id;
const stdout = item.json.stdout || '0';
const keyframeCount = parseInt(stdout.trim()) || 0;

if (keyframeCount === 0) {
  // No keyframes extracted — might be a very short video
  // Send original file to face recognition anyway
  return [{
    json: {
      ...item.json,
      _keyframePath: item.json.local_path,
      _keyframeIndex: 0,
      _totalKeyframes: 1,
      _isKeyframe: false
    }
  }];
}

// Create one item per keyframe
const results = [];
for (let i = 1; i <= Math.min(keyframeCount, 5); i++) {
  const kfPath = `/home/node/media_cache/keyframes/${mediaId}_${String(i).padStart(3, '0')}.jpg`;
  results.push({
    json: {
      ...item.json,
      _keyframePath: kfPath,
      _keyframeIndex: i,
      _totalKeyframes: keyframeCount,
      _isKeyframe: true
    }
  });
}

return results;

// ============================================================
// Parse Face Recognition Results
// ============================================================
// CompreFace returns an array of detected faces, each with:
//   - box: {x_min, y_min, x_max, y_max, probability}
//   - subjects: [{subject, similarity}]
//
// This node:
//   1. Filters matches above the confidence threshold
//   2. Deduplicates friend names (same person in multiple keyframes)
//   3. Prepares data for database update
// ============================================================

const THRESHOLD = parseFloat($env.FACE_CONFIDENCE_THRESHOLD) || 0.85;

// Collect all results (may be from multiple keyframes for videos)
const items = $input.all();
const allFaces = [];
const friendsSet = new Set();

for (const item of items) {
  const result = item.json.result || item.json.body?.result || [];

  for (const face of result) {
    const subjects = face.subjects || [];
    const bestMatch = subjects.length > 0 ? subjects[0] : null;

    if (bestMatch && bestMatch.similarity >= THRESHOLD) {
      friendsSet.add(bestMatch.subject);
      allFaces.push({
        subject: bestMatch.subject,
        similarity: Math.round(bestMatch.similarity * 1000) / 1000,
        box: face.box,
        keyframeIndex: item.json._keyframeIndex || 0
      });
    } else if (face.box && face.box.probability > 0.8) {
      // Face detected but not recognized — log it anyway
      allFaces.push({
        subject: '_unknown',
        similarity: bestMatch ? bestMatch.similarity : 0,
        box: face.box,
        keyframeIndex: item.json._keyframeIndex || 0
      });
    }
  }
}

// Get the original media file info from the first item
const firstItem = items[0].json;
const mediaId = firstItem.id;
const friendsList = Array.from(friendsSet).sort().map(f => f.replace(/'/g, "''"));

return [{
  json: {
    mediaId: mediaId,
    gdriveFileId: firstItem.gdrive_file_id || firstItem.gdriveFileId,
    originalFilename: firstItem.original_filename || firstItem.originalFilename,
    isVideo: firstItem.is_video || firstItem.isVideo || false,
    takenAt: firstItem.taken_at || firstItem.takenAt,
    localPath: firstItem.local_path || firstItem.localPath,
    facesDetected: allFaces.length,
    facesRecognized: JSON.stringify(allFaces).replace(/'/g, "''"),
    friendsIdentified: friendsList,
    friendCount: friendsList.length,
    // For display
    friendNames: friendsList.join(', ') || 'No friends recognized',
  }
}];

// ============================================================
// Session Clustering
// ============================================================
// Groups photos into "hangout sessions" using a 6-hour time window.
// Logic:
//   1. Look at the photo's taken_at timestamp
//   2. Find the most recent session that ended within 6 hours
//   3. If found → add to that session
//   4. If not → create a new session
//
// The session_id is a deterministic hash based on the 6-hour window,
// so the same photo always maps to the same session regardless of
// processing order.
// ============================================================

const SESSION_WINDOW_HOURS = 6;
const item = $input.first();
const takenAt = new Date(item.json.takenAt || new Date());

// Calculate session window start
// Round down to nearest 6-hour block
const msPerWindow = SESSION_WINDOW_HOURS * 60 * 60 * 1000;
const windowStart = new Date(Math.floor(takenAt.getTime() / msPerWindow) * msPerWindow);
const windowEnd = new Date(windowStart.getTime() + msPerWindow);

// Create a deterministic session key from the window
const sessionKey = `session_${windowStart.toISOString().split('T')[0]}_${windowStart.getHours().toString().padStart(2, '0')}`;

// Generate a readable session name
const dateStr = windowStart.toLocaleDateString('en-IN', { weekday: 'short', month: 'short', day: 'numeric' });
const timeStr = windowStart.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
const sessionName = `Hangout ${dateStr} ${timeStr}`;

return [{
  json: {
    ...item.json,
    sessionKey: sessionKey,
    sessionName: sessionName,
    windowStart: windowStart.toISOString(),
    windowEnd: windowEnd.toISOString(),
  }
}];
